int main(void)
{
  struct test_file * files;
  struct test_file * cur;
  unsigned int count = 0;

  files = test_list_files("data/input");
  for (cur = files; cur != NULL; cur = cur->next) {
    char * expected;
    char * data;
    const char * detected;
    size_t length;

    expected = test_stem(cur->path);
    data = test_read_file(cur->path, &length);
    detected = detect_fixture_charset(cur->path, (unsigned char *) data,
        length);
    if (strcmp(expected, detected) != 0) {
      fprintf(stderr, "charset-detection: %s expected %s, got %s\n",
          cur->path, expected, detected);
      abort();
    }
    free(data);
    free(expected);
    count++;
  }
  test_free_files(files);

  printf("charset_detection_test: %u fixtures checked\n", count);
  return 0;
}
```

#### main (unittest/imap-utf7/main.c:42)

```c
int main(void)
{
  const char * input = "~peter/mail/&U,BTFw-/&ZeVnLIqe-";
  const char * expected[] = {
    "~peter",
    "mail",
    "\xe5\x8f\xb0\xe5\x8c\x97",
    "\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e"
  };
  char * copy = strdup(input);
  char * token;
  char * saveptr = NULL;
  unsigned int index = 0;

  assert(copy != NULL);
  token = strtok_r(copy, "/", &saveptr);
  while (token != NULL) {
    assert(index < sizeof(expected) / sizeof(expected[0]));
    check_decode(token, expected[index]);
    index++;
    token = strtok_r(NULL, "/", &saveptr);
  }
  assert(index == sizeof(expected) / sizeof(expected[0]));
  free(copy);

  check_round_trip("&", "&-");
  check_round_trip("~peter/mail/\xe5\x8f\xb0\xe5\x8c\x97/\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e",
      "~peter/mail/&U,BTFw-/&ZeVnLIqe-");

  /* RFC 2152 examples adapted to IMAP modified UTF-7's shift character. */
  check_round_trip("A\xe2\x89\xa2\xce\x91.", "A&ImIDkQ-.");
  check_round_trip("Hi Mom -\xe2\x98\xba-!", "Hi Mom -&Jjo--!");
  check_round_trip("\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e", "&ZeVnLIqe-");
  check_round_trip("Item 3 is \xc2\xa3" "1.", "Item 3 is &AKM-1.");

  puts("imap_utf7_test: ok");
  return 0;
}
```

