char * test_stem(const char * path)
{
  const char * base = test_basename(path);
  const char * dot = strrchr(base, '.');
  size_t len = dot == NULL ? strlen(base) : (size_t) (dot - base);
  char * result = malloc(len + 1);

  assert(result != NULL);
  memcpy(result, base, len);
  result[len] = '\0';
  return result;
}
